input.new_string:
/****************************************************************************
 * Name: sg2000_boardinitialize
 *
 * Description:
 *   All SG2000 architectures must provide the following entry point.
 *   This entry point is called early in the initialization -- after all
 *   memory has been configured and mapped but before any devices have been
 *   initialized.
 *
 ****************************************************************************/

void sg2000_boardinitialize(void)
{
  /* Initialize on-board LEDs */

  board_autoled_initialize();

  /* Ensure the UART is in a clean state before the kernel proper starts.
   * The 16550 driver's u16550_setup() reads the IER but never clears it,
   * so any interrupts enabled by U-Boot remain active. When uart_open()
   * later calls uart_attach() -> up_enable_irq(), a pending UART interrupt
   * (e.g., THRE from the empty TX FIFO) would fire immediately and could
   * deadlock with the spinlock held by uart_open().
   *
   * Fix: explicitly disable all UART interrupts before the kernel starts.
   * The IER is at offset 1 (REGINCR=4, so byte offset 4 from base).
   */

  {
    volatile uint32_t *uart_base = (volatile uint32_t *)0x04140000;

    /* Disable all UART interrupts (write 0 to IER at base+1 word) */
    uart_base[1] = 0;

    /* Drain any residual data from the RX FIFO */
    while (uart_base[5] & (1 << 0))   /* LSR bit 0 = Data Ready */
      {
        (void)uart_base[0];            /* Read RBR to discard byte */
      }
  }
}

